//! Native symbol extraction, ported per language from WrongStack's parsers.
//! Each port is validated against known answers generated by the original
//! TypeScript implementation (`contracts/fixtures/parser-kat.json`).

pub mod generic;
pub mod go;
pub mod imports;
pub mod infra;
pub mod json;
pub mod py;
pub mod rs;
pub mod treesitter;
pub mod ts;
pub mod yaml;

use serde::Serialize;

use crate::js::{self, U16};

/// A parsed symbol before it is written (the parser's `Symbol` shape).
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ParsedSymbol {
    pub kind: &'static str,
    pub name: String,
    pub line: usize,
    /// UTF-16 code units from the start of the line.
    pub col: usize,
    pub signature: String,
    pub doc_comment: String,
    pub scope: String,
    pub text: String,
    /// Parser-supplied export flag (`Symbol.isExported`); `None` lets the
    /// writer infer it.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub is_exported: Option<bool>,
    /// Parser-supplied end line (`Symbol.endLine`); used when `>= line`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub end_line: Option<usize>,
}

impl ParsedSymbol {
    /// `makeSymbol` in the JSON/YAML parsers: `text = "${name} ${signature}".trim()`.
    pub fn simple(
        kind: &'static str,
        name: &U16,
        line: usize,
        col: usize,
        signature: &U16,
    ) -> Self {
        let mut text = name.to_vec();
        text.push(0x20);
        text.extend_from_slice(signature);
        Self {
            kind,
            name: js::string(name),
            line,
            col,
            signature: js::string(signature),
            doc_comment: String::new(),
            scope: String::new(),
            text: js::string(js::trim(&text)),
            is_exported: None,
            end_line: None,
        }
    }
}

/// Parser output for one file.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize)]
pub struct Parsed {
    pub symbols: Vec<ParsedSymbol>,
    /// Set when the TypeScript parser would also have produced references
    /// that this port does not implement yet; such a file must not be
    /// written natively.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub unsupported: Option<String>,
    /// References after WrongStack's `withRelations` (regex import fallback
    /// plus language stamping); empty for languages without import patterns.
    pub refs: Vec<ParsedRef>,
}

/// A parsed reference (WrongStack's `Ref` before indexing assigns `fromId`
/// and resolves the target).
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ParsedRef {
    pub to_name: String,
    pub call_type: &'static str,
    pub line: usize,
    pub lang: &'static str,
    /// Module specifier, verbatim, for `import` refs.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub module: Option<String>,
}

/// What a toolchain route returns for a list of files.
#[derive(Debug, Default)]
pub struct Batch {
    /// One entry per file, in order. `None`: nothing could parse the file in
    /// this run; no rows are written for it and its previous rows stay.
    pub parsed: Vec<Option<Parsed>>,
    /// What ran in a reduced way (a missing or failing helper), for the
    /// run's report. Never source text.
    pub notes: Vec<String>,
}

impl Batch {
    pub(crate) fn of(parsed: Vec<Parsed>) -> Self {
        Batch {
            parsed: parsed.into_iter().map(Some).collect(),
            notes: Vec::new(),
        }
    }
}

/// Whether a run must refuse what it cannot do exactly as WrongStack does
/// (`WRONGINDEX_NATIVE_STRICT`, set by the service when WrongStack's own
/// engine is there to take a refused project). Without it a missing or
/// failing helper degrades per file, as WrongStack's parsers do, and the
/// run says so in its report.
pub(crate) fn strict() -> bool {
    std::env::var_os("WRONGINDEX_NATIVE_STRICT").is_some()
}

/// One helper program's failures across the chunks of a run.
///
/// The first chunk the program cannot complete (not started, timed out,
/// non-zero exit, undecodable output) goes through `fallback`, and so does
/// every later chunk without starting the program again: a hostile checkout
/// must not keep a job busy for one timeout per chunk (WI-604). In strict
/// mode the failure is the run's, as before.
pub(crate) struct Degrade {
    strict: bool,
    tripped: std::sync::atomic::AtomicBool,
    why: std::sync::Mutex<Option<String>>,
}

impl Degrade {
    pub(crate) fn new(strict: bool) -> Self {
        Degrade {
            strict,
            tripped: std::sync::atomic::AtomicBool::new(false),
            why: std::sync::Mutex::new(None),
        }
    }

    pub(crate) fn run<T>(
        &self,
        helper: impl FnOnce() -> Result<T, String>,
        fallback: impl FnOnce() -> T,
    ) -> Result<T, String> {
        use std::sync::atomic::Ordering::SeqCst;
        if !self.tripped.load(SeqCst) {
            match helper() {
                Ok(v) => return Ok(v),
                Err(e) if self.strict => return Err(e),
                Err(e) => {
                    self.tripped.store(true, SeqCst);
                    self.why
                        .lock()
                        .unwrap_or_else(|p| p.into_inner())
                        .get_or_insert(e);
                }
            }
        }
        Ok(fallback())
    }

    /// The note for the report: `what` and the first failure.
    pub(crate) fn notes(self, what: &str) -> Vec<String> {
        self.why
            .into_inner()
            .unwrap_or_else(|p| p.into_inner())
            .map(|why| format!("{what} ({why})"))
            .into_iter()
            .collect()
    }
}

/// Languages parsed natively: [`parse_file`] reproduces `parseFileContent`
/// for each of them.
pub fn is_native_lang(lang: &str) -> bool {
    matches!(lang, "json" | "yaml" | "rs" | "py" | "go")
        || generic::LANGS.contains(&lang)
        || ts::LANGS.contains(&lang)
        || treesitter::LANGS.contains(&lang)
}

/// `parseFileContent(file, content, lang)` (`parser-dispatch.ts`): the
/// language's parser, then `withRelations` - the regex import fallback when
/// the parser produced no refs, and `lang` stamped on every ref. YAML files
/// carry the refs of `parseInfraArtifact` (compose, workflows, OpenAPI,
/// Kubernetes, and any other kind their name selects); its symbols are
/// dropped, as `yaml-parser.ts` does.
pub fn parse_file(file: &str, lang: &'static str, content: &U16) -> Parsed {
    let parsed = match lang {
        "json" => json::parse(file, content, None),
        "yaml" => {
            let mut parsed = yaml::parse(content);
            let infra = infra::parse(file, content, "yaml");
            if let Some(why) = infra.unsupported {
                parsed.unsupported = Some(why);
            } else if !infra.refs.is_empty() {
                parsed.refs = infra.refs;
            }
            parsed
        }
        // `rs::parse` already applies `withRelations`.
        "rs" => return rs::parse(content),
        // `ts-parser.ts` refs are stamped with `lang`; TS/JS have no regex
        // import fallback.
        l if ts::LANGS.contains(&l) => return ts::parse(file, l, content),
        l if generic::LANGS.contains(&l) => generic::parse(file, l, content),
        // Python and Go run through their toolchains in batches:
        // [`py::parse_all`], [`go::parse_all`].
        l if l == "py" || l == "go" || treesitter::LANGS.contains(&l) => {
            return Parsed {
                unsupported: Some(format!("{lang} files are parsed in toolchain batches")),
                ..Parsed::default()
            };
        }
        other => {
            return Parsed {
                unsupported: Some(format!("language {other}")),
                ..Parsed::default()
            };
        }
    };
    with_relations(parsed, content, lang)
}

/// `withRelations(parsed, content, lang)`. Every ported parser stamps its
/// refs with `lang` already, so only the import fallback remains.
fn with_relations(mut parsed: Parsed, content: &U16, lang: &'static str) -> Parsed {
    if parsed.refs.is_empty() && imports::has_import_patterns(lang) {
        parsed.refs = imports::extract_imports(content, lang);
    }
    parsed
}
